import { ART_ENTRIES } from "./art-entries";
import type { ArtSlot } from "./art-slots";

export interface ArtEntry {
  readonly src: string;
  readonly width: number;
  readonly height: number;
  /** Mean colour of an opaque image, painted behind it while it loads; "transparent" for sprites. */
  readonly background: string;
}

export type ArtManifest = Readonly<Partial<Record<ArtSlot, ArtEntry>>>;

/** The accepted designer images, generated by `scripts/build-art.mjs`; every other slot is a placeholder. */
export const ART_MANIFEST: ArtManifest = ART_ENTRIES;

/** Shown first: the title screen, the sky behind the tabs and the building on the Observe tab. */
export const CRITICAL_SLOTS: readonly ArtSlot[] = ["key-art", "sky-far", "observatory-building"];

export function manifestUrls(manifest: ArtManifest = ART_MANIFEST): string[] {
  return Object.values(manifest).map((entry) => entry.src);
}

export function criticalUrls(manifest: ArtManifest = ART_MANIFEST): string[] {
  return CRITICAL_SLOTS.flatMap((slot) => {
    const entry = manifest[slot];
    return entry ? [entry.src] : [];
  });
}
